// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/panel-loops.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * What the feature loops of the small product scenes (Panels.tsx) share: the
 * hand-over to the visitor, Claude Code's input box for Quick Chat, and the
 * command palette's search, ported from the app (src/fuzzyMatch.ts and
 * src/panels/CommandPalette.tsx) so a typed query filters and ranks rows the
 * way the app does. The loops themselves live next to their panels.
 */
import { Fragment, useLayoutEffect, useRef, type ReactNode, type RefObject } from "react";
import { parseAnsi, type Run } from "./ansi";
import { CAPTURES, type CaptureId } from "./captures";
import { useScenePlayback, useVisitorTakeover, type Wait } from "./playback";

/* ------------------------------------------------------------ hand-over -- */

/**
 * Plays `round` in a loop (useScenePlayback) for the panel at `element`
 * while its scene is on screen. Any press or keystroke anywhere in the scene
 * hands it to the visitor (useVisitorTakeover): the loop stops for good and
 * `onStop` puts the transient state back. A dropdown the visitor opens
 * themselves, or the pinned one coming back after another was open, is
 * theirs from the start and never plays. Returns whether the visitor has it.
 */
export function usePanelLoop(element: RefObject<HTMLElement>, round: (wait: Wait) => Promise<void>, onStop?: () => void): boolean {
  const scene = useRef<HTMLElement | null>(null);
  const handedOver = useVisitorTakeover(element);

  // The whole scene is what has to be on screen, since a panel can run off
  // its card. A layout effect, so it is known before the playback's effect looks.
  useLayoutEffect(() => {
    scene.current = element.current?.closest<HTMLElement>(".pz") ?? null;
  }, [element]);

  useScenePlayback(scene, round, { stopped: handedOver, onStop });
  return handedOver;
}

/* ------------------------------------------------------ quick chat input -- */

type Line = Run[];

const plainText = (runs: Line) => runs.map((run) => run.text).join("");

/**
 * The capture's session before its last question was sent: the banner, then
 * Claude Code's input box with `typed` in it and the cursor after it. The
 * banner, rules and footer are the capture's own lines.
 */
export function composeLines(id: CaptureId, typed: string): Line[] {
  const lines = parseAnsi(CAPTURES[id]);
  const plain = lines.map(plainText);
  let question = -1;
  let input = -1;
  plain.forEach((line, i) => {
    if (/^❯ \S/.test(line)) question = i;
    // The empty prompt between the input box's two rules.
    if (/^❯\s*$/.test(line)) input = i;
  });
  if (question < 0 || input < 1) return lines;
  const cursor: Run = { text: " ", style: { inverse: true } };
  return [
    ...lines.slice(0, question),
    ...lines.slice(input - 1).map((runs, i) => (i === 1 ? [...runs, { text: typed, style: {} }, cursor] : runs)),
  ];
}

/* ------------------------------------------------------- palette search -- */

interface FuzzyMatch {
  score: number;
  /** Indexes into the text of the matched query characters, in order. */
  positions: number[];
}

const SEPARATOR = /[\s\-_/.:,()&·…]/;
const NONE = Number.NEGATIVE_INFINITY;

function wordStart(text: string, index: number): boolean {
  if (index === 0) return true;
  const before = text[index - 1];
  return SEPARATOR.test(before) || (/[a-z0-9]/.test(before) && /[A-Z]/.test(text[index]));
}

// The app's subsequence match: every query character must appear in order,
// and the best alignment favours word starts and consecutive runs.
function fuzzyMatch(query: string, text: string): FuzzyMatch | null {
  const needle = query.toLowerCase().replace(/\s+/g, "");
  if (!needle) return { score: 0, positions: [] };
  const haystack = text.toLowerCase();
  const n = text.length;
  const m = needle.length;
  if (m > n) return null;
  let previous: number[] = new Array<number>(n).fill(NONE);
  const back: Int32Array[] = [];
  for (let i = 0; i < m; i++) {
    const current: number[] = new Array<number>(n).fill(NONE);
    const from = new Int32Array(n).fill(-1);
    // The best previous-character score at least two positions back (a gap).
    let gapBest = NONE;
    let gapAt = -1;
    for (let j = 0; j < n; j++) {
      if (i > 0 && j >= 2 && previous[j - 2] > gapBest) {
        gapBest = previous[j - 2];
        gapAt = j - 2;
      }
      if (haystack[j] !== needle[i]) continue;
      const bonus = 1 + (wordStart(text, j) ? 8 : 0);
      if (i === 0) {
        current[j] = bonus + (j === 0 ? 6 : 0) - Math.min(j, 10) * 0.2;
        continue;
      }
      const chained = j >= 1 && previous[j - 1] > NONE ? previous[j - 1] + 5 : NONE;
      const jumped = gapBest > NONE ? gapBest - 1 : NONE;
      if (chained === NONE && jumped === NONE) continue;
      if (chained >= jumped) {
        current[j] = chained + bonus;
        from[j] = j - 1;
      } else {
        current[j] = jumped + bonus;
        from[j] = gapAt;
      }
    }
    back.push(from);
    previous = current;
  }
  let end = -1;
  let score = NONE;
  for (let j = 0; j < n; j++) {
    if (previous[j] > score) {
      score = previous[j];
      end = j;
    }
  }
  if (end < 0) return null;
  const positions = new Array<number>(m);
  for (let i = m - 1, j = end; i >= 0; i--) {
    positions[i] = j;
    j = back[i][j];
  }
  // Among equal alignments, the shorter text is the closer match.
  return { score: score - (n - m) * 0.01, positions };
}

/** A row the palette can find. */
export interface Searchable {
  group: string;
  label: string;
  detail?: string;
  /** Extra words that find the row but are not shown. */
  keywords?: string;
}

export interface Ranked<T extends Searchable> {
  item: T;
  score: number;
  positions: number[];
}

/**
 * The app's search for a typed query: rows whose label or secondary text
 * match, grouped, with groups and rows ordered by their best match (stable
 * for ties). A label hit outranks the same hit in the secondary text, and a
 * help page ranks just under something to do.
 */
export function searchPalette<T extends Searchable>(items: T[], query: string): { group: string; rows: Ranked<T>[] }[] {
  const ranked: Ranked<T>[] = [];
  for (const item of items) {
    const label = fuzzyMatch(query, item.label);
    const extra = fuzzyMatch(query, [item.detail, item.keywords].filter(Boolean).join(" "));
    const bias = item.group === "Help" ? -1 : 0;
    if (label && (!extra || label.score >= extra.score - 4)) ranked.push({ item, score: label.score + bias, positions: label.positions });
    else if (extra) ranked.push({ item, score: extra.score - 4 + bias, positions: [] });
  }
  const byGroup = new Map<string, Ranked<T>[]>();
  for (const entry of ranked) byGroup.set(entry.item.group, [...(byGroup.get(entry.item.group) ?? []), entry]);
  return [...byGroup]
    .map(([group, rows]) => ({ group, rows: [...rows].sort((a, b) => b.score - a.score) }))
    .sort((a, b) => b.rows[0].score - a.rows[0].score);
}

/** A label with the matched characters marked, as the palette shows it. */
export function Highlight({ text, positions }: { text: string; positions: number[] }): ReactNode {
  if (!positions.length) return text;
  const marks = new Set(positions);
  const parts: ReactNode[] = [];
  let run = "";
  let marked = false;
  const flush = (key: number) => {
    if (run) parts.push(marked ? <mark key={key}>{run}</mark> : <Fragment key={key}>{run}</Fragment>);
    run = "";
  };
  for (let index = 0; index < text.length; index++) {
    const next = marks.has(index);
    if (next !== marked) {
      flush(index);
      marked = next;
    }
    run += text[index];
  }
  flush(text.length);
  return parts;
}
